ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';DOWN=DOC/'downloads';RUN=ROOT/'runs/btc-capacity-20261002';DATA=ROOT/'data/btc-premium-20261002'
def run():
 s=read(RUN/'summary.json');v=read(RUN/'verification.json');rep=read(RUN/'reproduction.json');sel=read(RUN/'selection.json');fore=read(RUN/'forecast-summary.json');unc=read(RUN/'uncertainty.json');assert len(s)==v['accounts']==60 and rep['all_bytes_equal'] and not sel['passed'];rows=[];base=[];annual=[];cost=[];ci=[]
